import{_ as t,o as a,a as l,b as d}from"./app.BGziXukh.js";const o=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetReduceType.md","filePath":"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetReduceType.md","outlineHeaders":[{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1795161712000}'),r={name:"api/SIMD-API/adv_api/HCCL_communication/HCCL_Tiling/SetReduceType.md"};function i(c,e,h,n,s,p){return a(),l("div",null,[...e[0]||(e[0]=[d(`<div><article class="markdown-body"><h1>SetReduceType</h1><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>设置Reduce操作类型，仅对有归约操作的通信任务生效。</p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>uint32_t SetReduceType(uint32_t reduceType, uint8_t dstDataType = 0, uint8_t srcDataType = 0)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>reduceType</td><td>输入</td><td>归约操作类型，仅对有归约操作的通信任务生效。uint32_t类型，取值详见<a href="../HCCL_Kernel/HCCL_usage.html#table2469980529">表2</a>参数说明。支持的操作类型及约束请参见<a href="../HCCL_Kernel/AllReduce.html#op%E8%AF%B4%E6%98%8E">AllReduce的op说明</a>和<a href="../HCCL_Kernel/ReduceScatter.html#op%E8%AF%B4%E6%98%8E">ReduceScatter的op说明</a>。</td></tr><tr><td>dstDataType</td><td>输入</td><td>通信任务中输出数据的数据类型。uint8_t类型，该参数的取值范围请参考<a href="../HCCL_Kernel/HCCL_usage.html#table116710585514">表1</a>。<span data-filter="950"><br><br>Ascend 950PR&amp;950DT系列产品，不同通信任务支持的输出数据类型不同，具体为：<br>对于AllReduce、AllGather、AllToAll、AllToAllV、AllToAllVWrite通信任务：输出的数据类型必须与输入的数据类型一致。各通信任务支持的输入数据类型请参考srcDataType。<br>对于ReduceScatter通信任务，AI CPU作为服务端时，输出的数据类型须与输入一致；CCU作为服务端时，输入的数据类型为int16_t、half、bfloat16_t、int32_t、float时，输出的数据类型须与其一致。int8_t的输入输出类型组合及算法约束请参见<a href="../HCCL_Kernel/ReduceScatter.html#op%E8%AF%B4%E6%98%8E">ReduceScatter的op说明</a>。</span></td></tr><tr><td>srcDataType</td><td>输入</td><td>通信任务中输入数据的数据类型。uint8_t类型，该参数的取值范围请参考<a href="../HCCL_Kernel/HCCL_usage.html#table116710585514">表1</a>。<span data-filter="950"><br><br>Ascend 950PR&amp;950DT系列产品，CCU作为服务端时，不同通信任务支持的输入数据类型如下：<br>AllReduce通信任务：支持的数据类型及约束请参见<a href="../HCCL_Kernel/AllReduce.html#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">AllReduce数据类型</a>。<br>AllGather、AllToAll、AllToAllV、AllToAllVWrite通信任务：支持的输入类型为int8_t、uint8_t、hifloat8_t、fp8_e5m2_t、fp8_e4m3fn_t、int16_t、uint16_t、half、bfloat16_t、int32_t、uint32_t、float、int64_t、double。<br>ReduceScatter通信任务：支持的数据类型及约束请参见<a href="../HCCL_Kernel/ReduceScatter.html#%E6%95%B0%E6%8D%AE%E7%B1%BB%E5%9E%8B">ReduceScatter数据类型</a>。</span></td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><ul><li>0表示设置成功。</li><li>非0表示设置失败。</li></ul><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><div data-filter="950"><p>对于Ascend 950PR&amp;950DT系列产品，该接口仅设置Tiling配置，不校验通信服务端及通信算法是否支持对应的数据类型与归约操作组合。配置时须满足<a href="../HCCL_Kernel/AllReduce.html#op%E8%AF%B4%E6%98%8E">AllReduce</a>或<a href="../HCCL_Kernel/ReduceScatter.html#op%E8%AF%B4%E6%98%8E">ReduceScatter</a>的约束，并与Hccl对象选择的服务端类型保持一致。</p></div><div data-filter="A3"><p>对于Atlas A3系列产品，该接口暂不支持使用。</p></div><div data-filter="910b"><p>对于Atlas A2系列产品，该接口暂不支持使用。</p></div><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>本接口的调用示例请见<a href="SetOpType.html#%E8%B0%83%E7%94%A8%E7%A4%BA%E4%BE%8B">调用示例</a>。</p></article></div>`,1)])])}const u=t(r,[["render",i]]);export{o as __pageData,u as default};
